"""Solve a slippery grid world with dynamic programming: policy evaluation, policy iteration and value iteration."""

import numpy as np

LAYOUT = ["...+",
          ".#.-",
          "...."]          # + goal (reward +1), - pit (reward -1), # wall; the agent starts bottom left
ACTIONS = {"up": (-1, 0), "right": (0, 1), "down": (1, 0), "left": (0, -1)}
ARROWS = {"up": "^", "right": ">", "down": "v", "left": "<"}
STEP_REWARD, SLIP, GAMMA = -0.04, 0.1, 0.99


class GridWorld:
    """Moves go the intended way with probability 0.8 and slip to each side with probability 0.1."""

    def __init__(self):
        self.rows, self.cols = len(LAYOUT), len(LAYOUT[0])
        self.states = [(r, c) for r in range(self.rows) for c in range(self.cols) if LAYOUT[r][c] != "#"]

    def terminal(self, s):
        return LAYOUT[s[0]][s[1]] in "+-"

    def move(self, s, delta):
        r, c = s[0] + delta[0], s[1] + delta[1]
        if 0 <= r < self.rows and 0 <= c < self.cols and LAYOUT[r][c] != "#":
            return (r, c)
        return s                    # bumping into a wall or the edge leaves the agent where it is

    def transitions(self, s, action):
        """A list of (probability, next state, reward) for taking action in state s."""
        dr, dc = ACTIONS[action]
        outcomes = [(1 - 2 * SLIP, (dr, dc)), (SLIP, (dc, dr)), (SLIP, (-dc, -dr))]   # intended, and both sides
        result = []
        for p, delta in outcomes:
            s2 = self.move(s, delta)
            cell = LAYOUT[s2[0]][s2[1]]
            result.append((p, s2, STEP_REWARD + (1.0 if cell == "+" else -1.0 if cell == "-" else 0.0)))
        return result


def q_value(env, V, s, a):
    # TODO: the one-step lookahead: the sum over (p, s2, r) in env.transitions(s, a) of p * (r + GAMMA * V[s2]),
    #  where V of a terminal state is always 0
    return 0.0


def policy_evaluation(env, policy, theta=1e-8):
    """policy[s] maps each action to its probability. Sweeps until no value changes by more than theta."""
    V = {s: 0.0 for s in env.states}
    sweeps = 0
    while True:
        delta, sweeps = 0.0, sweeps + 1
        for s in env.states:
            if env.terminal(s):
                continue
            new = sum(prob * q_value(env, V, s, a) for a, prob in policy[s].items())
            delta, V[s] = max(delta, abs(new - V[s])), new
        if delta < theta:
            return V, sweeps


def greedy(env, V):
    return {s: {max(ACTIONS, key=lambda a: q_value(env, V, s, a)): 1.0} for s in env.states}


def policy_iteration(env):
    policy = {s: {"up": 1.0} for s in env.states}
    for iteration in range(1, 100):
        V, _ = policy_evaluation(env, policy)
        improved = greedy(env, V)
        if improved == policy:
            return policy, V, iteration
        policy = improved


def value_iteration(env, theta=1e-8):
    V = {s: 0.0 for s in env.states}
    sweeps = 0
    while True:
        delta, sweeps = 0.0, sweeps + 1
        for s in env.states:
            if env.terminal(s):
                continue
            # TODO: the Bellman optimality backup: the largest q_value over the four actions
            new = V[s]
            delta, V[s] = max(delta, abs(new - V[s])), new
        if delta < theta:
            return greedy(env, V), V, sweeps


def show(env, V, policy=None):
    for r in range(env.rows):
        cells = []
        for c in range(env.cols):
            s = (r, c)
            if LAYOUT[r][c] == "#":
                cells.append("  ####  ")
            elif env.terminal(s):
                cells.append(f"   {LAYOUT[r][c]}    ")
            else:
                arrow = ARROWS[next(iter(policy[s]))] if policy else " "
                cells.append(f"{V[s]:+.3f}{arrow} ")
        print("  " + "".join(cells))


def main():
    env = GridWorld()
    uniform = {s: {a: 0.25 for a in ACTIONS} for s in env.states}
    V, sweeps = policy_evaluation(env, uniform)
    print(f"== 1. The uniform random policy, evaluated in {sweeps} sweeps")
    show(env, V)
    policy, V_pi, iterations = policy_iteration(env)
    print(f"== 2. Policy iteration: stable after {iterations} improvements")
    show(env, V_pi, policy)
    vi_policy, V_vi, sweeps = value_iteration(env)
    print(f"== 3. Value iteration: converged in {sweeps} sweeps")
    show(env, V_vi, vi_policy)
    same = vi_policy == policy and all(abs(V_vi[s] - V_pi[s]) < 1e-6 for s in env.states)
    print("policy iteration and value iteration agree:", same)


if __name__ == "__main__":
    main()

"""Monte Carlo against TD(0) on the five-state random walk, where the true values are known exactly."""

import numpy as np

TRUE_V = np.arange(1, 6) / 6          # states A-E; terminating on the right pays 1, on the left 0


def episode(rng):
    """Start in the middle (C); step left or right with equal probability until either end."""
    s, states, = 2, [2]
    while True:
        s += rng.choice((-1, 1))
        if s < 0:
            return states, 0.0
        if s > 4:
            return states, 1.0
        states.append(s)


def td0(alpha, episodes, rng):
    V, errors = np.full(5, 0.5), []
    for _ in range(episodes):
        states, final = episode(rng)
        for i, s in enumerate(states):
            if i + 1 < len(states):
                target = V[states[i + 1]]              # reward 0 on the way, gamma = 1
            else:
                target = final                         # the last step reaches a terminal state
            # TODO: the TD(0) update: move V[s] a fraction alpha of the way towards target
            pass
        errors.append(np.sqrt(np.mean((V - TRUE_V) ** 2)))
    return np.array(errors)


def monte_carlo(alpha, episodes, rng):
    V, errors = np.full(5, 0.5), []
    for _ in range(episodes):
        states, final = episode(rng)
        for s in states:
            # TODO: constant-alpha Monte Carlo: every visit's return is the final reward (gamma = 1, no other
            #  rewards), so move V[s] a fraction alpha of the way towards it
            pass
        errors.append(np.sqrt(np.mean((V - TRUE_V) ** 2)))
    return np.array(errors)


def main():
    runs, episodes = 100, 100
    print(f"RMS error against the true values, averaged over {runs} runs")
    print(f"{'method':18} {'after 10':>9} {'after 50':>9} {'after 100':>10}")
    for name, method, alphas in [("TD(0)", td0, (0.05, 0.1, 0.15)), ("Monte Carlo", monte_carlo, (0.01, 0.02, 0.04))]:
        for alpha in alphas:
            rng = np.random.default_rng(0)
            errors = np.mean([method(alpha, episodes, rng) for _ in range(runs)], axis=0)
            print(f"{name + ', a=' + str(alpha):18} {errors[9]:9.3f} {errors[49]:9.3f} {errors[99]:10.3f}")


if __name__ == "__main__":
    main()

